questionvariables.text:
/* Randomly select angle A: 35, 40, 45, 50 or 55 degrees */
A: 35+5*rand(5);

/* Randomly select angle B: 60, 65, 70, 75 or 80 degrees */
B: 60+5*rand(5);

/* Randomly select the known side a: 8 to 15 cm */
side_a: 8+rand(8);

/* Calculate the third angle */
C: 180-A-B;

/* Calculate the unknown side b using the Sine Rule */
side_b: side_a*sin(B*%pi/180)/sin(A*%pi/180);

/* Round the answer to 2 decimal places */
ta1: round(side_b*100)/100;
